(() => {
const { store } = window.BarangayStore;

const app=document.getElementById('app');
const toast=document.getElementById('toast');
let page=location.hash.slice(1)||'dashboard', searchText='', reportPage=1, reportFilters={}, analyticsFilters={}, activityFilters={}, alertFilters={}, residentQuery='', alertQuery='', activityPageNumber=1,mobileSearchOpen=false;
let toastTimer;
const STATUS=['Submitted','Under Review','Verified','In Progress','Resolved','Closed','Rejected','Cancelled'];
const CATEGORIES=['Public Safety','Infrastructure','Health & Medical','Flood','Fire','Medical Emergency','Severe Weather','Crime or Security','General','Other'];
const SEVERITIES=['Low','Medium','High','Critical'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>s?new Date(s).toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'}):'—';
const dateTime=s=>s?new Date(s).toLocaleString('en-PH',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}):'—';
const timeAgo=s=>{const m=Math.max(0,Math.floor((Date.now()-new Date(s).getTime())/60000));return m<1?'just now':m<60?`${m} min ago`:m<1440?`${Math.floor(m/60)} hr ago`:date(s)};
function notify(message,error=false){toast.textContent=message;toast.classList.toggle('error',error);toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3200)}
function icon(name){const paths={dashboard:'<rect x="3" y="3" width="8" height="8" rx="1.5"/><rect x="13" y="3" width="8" height="5" rx="1.5"/><rect x="13" y="10" width="8" height="11" rx="1.5"/><rect x="3" y="13" width="8" height="8" rx="1.5"/>',reports:'<path d="M7 3h8l5 5v13H7a3 3 0 0 1-3-3V6a3 3 0 0 1 3-3Z"/><path d="M14 3v6h6M8 13h8M8 17h8"/>',map:'<path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',residents:'<circle cx="9" cy="8" r="3.5"/><path d="M2.5 20v-1.5a6.5 6.5 0 0 1 13 0V20M17 5a3.5 3.5 0 0 1 0 6.8M19 14a5 5 0 0 1 2.5 4.5V20"/>',analytics:'<path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/>',alerts:'<path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',activity:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',archives:'<path d="M4 5h16v4H4zM6 9v11h12V9M10 13h4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19 15 1.5 1-1.5 2.5-1.8-.5-1.5.9-.3 1.8h-3l-.5-1.7-1.7-.5-1.3 1.2-2.5-1.5.6-1.8-.9-1.5-1.8-.3v-3l1.7-.5.5-1.7L5.3 8.1l1.5-2.5 1.8.6 1.5-.9.3-1.8h3l.5 1.7 1.7.5 1.3-1.2 2.5 1.5-.6 1.8.9 1.5 1.8.3v3l-1.7.5z"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 4 4"/>',bell:'<path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',chevron:'<path d="m7 10 5 5 5-5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||''}</svg>`}
const nav=[['dashboard','Dashboard','dashboard'],['reports','Report Management','reports'],['map','Incident Map','map'],['residents','Resident Accounts','residents'],['analytics','Reports & Analytics','analytics'],['alerts','Emergency Alerts','alerts'],['activity','Activity Logs','activity'],['archives','Report Archives','archives'],['settings','Settings','settings']];
function setPage(next){page=next;location.hash=next;render()}
function shell(content){const d=store.get(),admin=d.admin,unread=d.notifications.filter(n=>!n.read).length,maintenance=d.settings.maintenance['Admin Website'],notice=maintenance?.enabled?`<div class="maintenance-notice"><strong>${esc(maintenance.title||'Admin website maintenance')}</strong><span>${esc(maintenance.message||'Maintenance mode is enabled for this local demo.')}</span>${maintenance.end?`<small>Expected completion: ${dateTime(maintenance.end)}</small>`:''}</div>`:'';return `<div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#dashboard"><span class="brand-mark">${icon('alerts')}</span><span class="brand-copy"><strong>Alert Barangay</strong><small>ADMIN PORTAL · LOCAL DEMO</small></span></a><div class="nav-label">WORKSPACE</div><nav class="nav-list">${nav.map(([key,label,ic],i)=>`${i===4?'<div class="nav-label nav-label-gap">MANAGEMENT</div>':''}<a class="nav-item ${page===key?'active':''}" href="#${key}" data-page="${key}"><span class="nav-icon">${icon(ic)}</span>${label}${key==='reports'&&d.reports.filter(r=>r.status==='Submitted').length?`<span class="nav-count">${d.reports.filter(r=>r.status==='Submitted').length}</span>`:''}${key==='alerts'&&d.alerts.some(a=>a.status==='Published')?'<span class="alert-dot"></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-help"><span class="help-icon">?</span><div><strong>Local demo mode</strong><small>Data saves in this browser</small></div></div><div class="sidebar-foot">Standalone admin demo <span>v1.0</span></div></div></aside><main class="main-area"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">☰</button><div class="breadcrumb"><span>Workspace</span><span class="crumb-sep">/</span><strong>${nav.find(x=>x[0]===page)?.[1]||'Dashboard'}</strong></div><div class="topbar-right"><label class="search-box ${mobileSearchOpen?'mobile-open':''}" data-action="mobile-search">${icon('search')}<input id="globalSearch" type="search" placeholder="Search reports..." value="${esc(searchText)}" aria-label="Search reports"><kbd>⌘ K</kbd></label><div class="notification-wrap"><button class="icon-button notification-button" data-action="notifications" aria-label="Notifications${unread?` · ${unread} unread`:''}">${icon('bell')}${unread?`<i>${unread}</i>`:''}</button></div><span class="top-divider"></span><div class="profile-wrap"><button class="profile-button" data-action="profile-menu"><span class="avatar">${admin.picture?`<img src="${esc(admin.picture)}" alt="">`:initials(admin.name)}</span><span class="profile-text"><strong>${esc(admin.name)}</strong><small>Barangay Administrator</small></span>${icon('chevron')}</button></div></div></header><div class="content">${notice}${content}<footer class="page-footer"><span>Alert Barangay Admin Portal <span class="footer-sep">·</span> Local sample data only</span><span>Standalone demo <b>·</b> Not connected to residents</span></footer></div></main><div id="popover"></div><div id="modal"></div></div>`}
function initials(name){return (name||'Admin').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function header(title,subtitle,button=''){return `<section class="welcome-row"><div><div class="eyebrow"><span class="live-dot"></span> BARANGAY SAN ISIDRO <span class="eyebrow-separator">·</span> ADMIN PORTAL</div><h1>${title}</h1><p>${subtitle}</p></div>${button}</section>`}
function btn(action,label,kind='primary',extra=''){return `<button class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`}
function selectFilter(label,key,options,value=''){return `<label class="filter-field"><span>${label}</span><select data-filter="${key}"><option value="">All ${label}</option>${options.map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`}
function empty(title,desc,button=''){return `<div class="empty-state"><span>⌕</span><strong>${title}</strong><p>${desc}</p>${button}</div>`}
function badge(text){return `<span class="status status-${String(text).toLowerCase().replace(/[^a-z]+/g,'-')}">${esc(text)}</span>`}
function residentStatus(r){return ['Active','Restricted','Blocked'].includes(r.status)?r.status:(r.restricted?'Restricted':'Active')}
function reportTable(rows,withActions=true){if(!rows.length)return empty('No reports found','Try changing your search or filters.');return `<div class="table-scroll"><table><thead><tr><th>REPORT</th><th>CATEGORY</th><th>LOCATION</th><th>DATE</th><th>SEVERITY</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="table-link" data-action="view-report" data-id="${r.id}"><strong>${esc(r.title)}</strong><small>#${esc(r.id)}${r.sample?' · SAMPLE':''}</small></button></td><td>${esc(r.category)}</td><td>${esc(r.location)}</td><td>${date(r.createdAt)}</td><td>${badge(r.severity)}</td><td>${badge(r.status)}</td><td class="actions-cell"><button class="tiny-btn" data-action="view-report" data-id="${r.id}">View</button>${withActions?`<button class="tiny-btn" data-action="edit-report" data-id="${r.id}">Edit</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}
function dashboard(){const d=store.get(),rs=d.reports,pending=rs.filter(r=>['Submitted','Under Review','Verified'].includes(r.status)).length,progress=rs.filter(r=>r.status==='In Progress').length,resolved=rs.filter(r=>['Resolved','Closed'].includes(r.status)).length,active=d.alerts.filter(a=>a.status==='Published').length;const stats=[['Total Reports',rs.length,'reports','blue'],['Pending Reports',pending,'reports','orange'],['In Progress',progress,'reports','violet'],['Resolved Reports',resolved,'reports','green'],['Total Residents',d.residents.length,'residents','sky'],['Active Emergency Alerts',active,'alerts','red']];const days=Array.from({length:7},(_,i)=>{const date=new Date();date.setDate(date.getDate()-6+i);const key=date.toDateString();return {label:date.toLocaleDateString('en',{weekday:'short'}),count:rs.filter(r=>new Date(r.createdAt).toDateString()===key).length}});const max=Math.max(1,...days.map(x=>x.count));const cats=[...new Set(rs.map(r=>r.category))].slice(0,5);const recent=[...rs].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,5);return `${header(`Good ${new Date().getHours()<12?'morning':'afternoon'}, ${esc(d.admin.name.split(' ')[0])} <span class="wave">✦</span>`,'Here is the current status of your barangay operations.',`<span class="date-chip">${new Date().toLocaleDateString('en-PH',{weekday:'long',month:'long',day:'numeric',year:'numeric'})}</span>`)}<section class="stat-grid">${stats.map(([label,value,target,color])=>`<button class="stat-card" data-action="stat-nav" data-target="${target}" data-label="${label}"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ${color}">${icon(target==='reports'?'reports':target==='alerts'?'alerts':'residents')}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${target==='reports'?'Updated from saved reports':target==='residents'?'Resident accounts':'Currently published'}</div></button>`).join('')}</section><section class="analytics-grid"><article class="panel reports-panel"><div class="panel-heading"><div><h2>Incident Reports</h2><p>Reports submitted over the last seven days</p></div>${btn('go-analytics','View analytics','subtle')}</div><div class="dashboard-bars">${days.map(x=>`<div class="bar-column"><span>${x.count}</span><div style="height:${Math.max(5,x.count/max*100)}%"></div><small>${x.label}</small></div>`).join('')}</div></article><article class="panel category-panel"><div class="panel-heading"><div><h2>Reports by Category</h2><p>Current report distribution</p></div></div><div class="category-bars">${cats.map((c,i)=>{const n=rs.filter(r=>r.category===c).length;return `<div><span>${esc(c)}</span><strong>${n}</strong><i><b style="width:${Math.max(8,n/rs.length*100)}%;background:${['#3978d5','#65a8e8','#7f73c9','#55b798','#e6a84b'][i]} "></b></i></div>`}).join('')}</div></article></section><section class="panel incidents-panel"><div class="panel-heading table-heading"><div><h2>Recent Incident Reports</h2><p>Latest reports saved in this browser</p></div><a class="text-link" href="#reports">View all →</a></div>${reportTable(recent,false)}</section><section class="lower-grid dashboard-lower"><article class="panel activity-panel"><div class="panel-heading"><div><h2>Recent Administrative Activities</h2><p>Latest actions by administrators</p></div><a class="text-link" href="#activity">Activity log →</a></div>${activityFeed(d.activity.slice(0,4))}</article><article class="panel alerts-panel"><div class="panel-heading"><div><h2>Emergency Alerts Overview</h2><p>${active} published alert${active===1?'':'s'}</p></div><a class="text-link" href="#alerts">Manage →</a></div>${alertSummary(d.alerts.filter(a=>a.status==='Published').slice(0,2))}</article></section>`}
function activityFeed(rows){return rows.length?`<div class="activity-list">${rows.map(a=>`<div class="activity-item"><span class="activity-avatar av-blue">${initials(a.admin)}</span><div><p><strong>${esc(a.admin)}</strong> ${esc(a.action.toLowerCase())} <b>${esc(a.affected)}</b></p><small>${dateTime(a.date)} · ${timeAgo(a.date)}</small></div></div>`).join('')}</div>`:empty('No activity yet','Administrative actions will appear here.')}
function alertSummary(rows){return rows.length?`<div class="alert-list">${rows.map(a=>`<div class="alert-card ${a.severity==='Critical'?'critical':'advisory'}"><span class="alert-symbol">!</span><div class="alert-copy"><div><strong>${esc(a.title)}</strong>${badge(a.severity)}</div><p>${esc(a.category)} · ${esc(a.location)}</p><small>Published ${timeAgo(a.createdAt)}</small></div></div>`).join('')}</div>`:empty('No active alerts','Published alerts will appear here.')}
function reportsPage(){const d=store.get();let rows=d.reports.filter(r=>!reportFilters.status||(reportFilters.status==='Pending'?['Submitted','Under Review','Verified'].includes(r.status):r.status===reportFilters.status)).filter(r=>!reportFilters.category||r.category===reportFilters.category).filter(r=>!reportFilters.severity||r.severity===reportFilters.severity).filter(r=>!reportFilters.from||r.createdAt.slice(0,10)>=reportFilters.from).filter(r=>!reportFilters.to||r.createdAt.slice(0,10)<=reportFilters.to).filter(r=>!searchText||`${r.id} ${r.title} ${r.category} ${r.location} ${r.description}`.toLowerCase().includes(searchText.toLowerCase()));rows.sort((a,b)=>reportFilters.sort==='oldest'?new Date(a.createdAt)-new Date(b.createdAt):new Date(b.createdAt)-new Date(a.createdAt));const pages=Math.max(1,Math.ceil(rows.length/8));reportPage=Math.min(reportPage,pages);const shown=rows.slice((reportPage-1)*8,reportPage*8);return `${header('Report Management','Review, assign, and track community incident reports.',btn('new-report','＋ New report'))}<section class="panel"><div class="filters"><label class="filter-field"><span>Search</span><input id="reportSearch" placeholder="Search reports..." value="${esc(searchText)}"></label>${selectFilter('Status','status',['Pending',...STATUS],reportFilters.status||'')}${selectFilter('Category','category',CATEGORIES,reportFilters.category||'')}${selectFilter('Severity','severity',SEVERITIES,reportFilters.severity||'')}<label class="filter-field"><span>From</span><input type="date" data-filter="from" value="${reportFilters.from||''}"></label><label class="filter-field"><span>To</span><input type="date" data-filter="to" value="${reportFilters.to||''}"></label><label class="filter-field"><span>Sort</span><select data-filter="sort"><option value="newest">Newest first</option><option value="oldest" ${reportFilters.sort==='oldest'?'selected':''}>Oldest first</option></select></label><button class="btn subtle" data-action="clear-report-filters">Clear</button></div>${reportTable(shown)}<div class="table-footer"><span>${rows.length?`Showing ${Math.min(rows.length,(reportPage-1)*8+1)}–${Math.min(rows.length,reportPage*8)} of ${rows.length}`:'0 results'}</span><div><button data-action="report-page" data-value="${Math.max(1,reportPage-1)}" ${reportPage===1?'disabled':''}>‹</button><span>Page ${reportPage} of ${pages}</span><button data-action="report-page" data-value="${Math.min(pages,reportPage+1)}" ${reportPage===pages?'disabled':''}>›</button></div></div></section>`}
function mapPage(){const d=store.get(),rows=d.reports.filter(r=>!reportFilters.status||(reportFilters.status==='Pending'?['Submitted','Under Review','Verified'].includes(r.status):r.status===reportFilters.status)).filter(r=>!reportFilters.category||r.category===reportFilters.category).filter(r=>!searchText||`${r.title} ${r.location} ${r.category}`.toLowerCase().includes(searchText.toLowerCase()));const lats=rows.map(r=>Number(r.lat)||0),lngs=rows.map(r=>Number(r.lng)||0),minLat=Math.min(...lats),maxLat=Math.max(...lats),minLng=Math.min(...lngs),maxLng=Math.max(...lngs);const position=(v,min,max)=>max===min?50:12+((v-min)/(max-min))*76;return `${header('Incident Map','Browse sample incident coordinates recorded with reports.') }<section class="panel map-filters"><div class="filters">${selectFilter('Status','status',['Pending',...STATUS],reportFilters.status||'')}${selectFilter('Category','category',CATEGORIES,reportFilters.category||'')}<span class="sample-note">Schematic map · sample locations, not live GPS</span></div></section><section class="panel map-panel"><div class="schematic-map"><div class="map-water"></div><div class="map-road road-a"></div><div class="map-road road-b"></div><div class="map-road road-c"></div><div class="map-park">SAN ISIDRO<br>COMMUNITY</div><div class="map-hall">BARANGAY HALL</div>${rows.map((r,i)=>`<button class="map-pin severity-${r.severity.toLowerCase()}" style="left:${position(Number(r.lng)||0,minLng,maxLng)}%;top:${100-position(Number(r.lat)||0,minLat,maxLat)}%" title="${esc(r.title)} · ${esc(r.location)}" data-action="view-report" data-id="${r.id}"><span>${i+1}</span></button>`).join('')}<div class="map-label label-n">N ↑</div></div><div class="map-legend"><strong>${rows.length} incidents shown</strong><span><i class="pin-dot critical"></i>Critical/high</span><span><i class="pin-dot medium"></i>Medium</span><span><i class="pin-dot low"></i>Low</span><span class="map-disclaimer">Sample coordinates are illustrative; map is schematic.</span></div></section><section class="panel"><div class="panel-heading table-heading"><div><h2>Mapped Incidents</h2><p>Click a marker or report to open its details</p></div></div>${reportTable(rows)}</section>`}
function residentsPage(){const d=store.get(),rows=d.residents.filter(r=>!residentQuery||`${r.name} ${r.email} ${r.address} ${r.id}`.toLowerCase().includes(residentQuery.toLowerCase())).filter(r=>!reportFilters.residentStatus||residentStatus(r)===reportFilters.residentStatus);return `${header('Resident Accounts','Manage resident profiles and account access within the administrator portal.',btn('new-resident','＋ Add resident'))}<section class="panel"><div class="filters"><label class="filter-field"><span>Search residents</span><input id="residentSearch" value="${esc(residentQuery)}" placeholder="Name, email, address"></label>${selectFilter('Account status','resident-residentStatus',['Active','Restricted','Blocked'],reportFilters.residentStatus||'')}<span class="sample-note">${rows.length} of ${d.residents.length} residents</span></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>RESIDENT</th><th>CONTACT</th><th>ADDRESS</th><th>JOINED</th><th>ACCOUNT STATUS</th><th>ADMIN ACTIONS</th></tr></thead><tbody>${rows.map(r=>{const status=residentStatus(r);return `<tr><td><button class="table-link" data-action="view-resident" data-id="${r.id}"><strong>${esc(r.name)}</strong><small>${esc(r.id)}${r.sample?' · SAMPLE':''}</small></button></td><td>${esc(r.email)}<small>${esc(r.phone)}</small></td><td>${esc(r.address)}</td><td>${date(r.createdAt)}</td><td>${badge(status)}</td><td class="actions-cell"><button class="tiny-btn" data-action="edit-resident" data-id="${r.id}">Edit</button>${status==='Active'?`<button class="tiny-btn" data-action="resident-status" data-id="${r.id}" data-status="Restricted">Restrict</button><button class="tiny-btn danger-text" data-action="resident-status" data-id="${r.id}" data-status="Blocked">Block</button>`:`<button class="tiny-btn" data-action="resident-status" data-id="${r.id}" data-status="Active">Reactivate</button>`}</td></tr>`}).join('')}</tbody></table></div>`:empty('No residents found','Try a different search or add an account.')}</section>`}
function analyticsPage(){const d=store.get(),rows=d.reports.filter(r=>!analyticsFilters.category||r.category===analyticsFilters.category).filter(r=>!analyticsFilters.status||r.status===analyticsFilters.status).filter(r=>!analyticsFilters.from||r.createdAt.slice(0,10)>=analyticsFilters.from).filter(r=>!analyticsFilters.to||r.createdAt.slice(0,10)<=analyticsFilters.to);const groups=(key,items)=>items.map(x=>[x,rows.filter(r=>r[key]===x).length]);const cats=[...new Set(d.reports.map(r=>r.category))],statuses=[...new Set(d.reports.map(r=>r.status))];const monthly=Array.from({length:6},(_,i)=>{const dt=new Date();dt.setMonth(dt.getMonth()-(5-i));return {label:dt.toLocaleDateString('en',{month:'short'}),n:rows.filter(r=>{const x=new Date(r.createdAt);return x.getMonth()===dt.getMonth()&&x.getFullYear()===dt.getFullYear()}).length}});return `${header('Reports & Analytics','Explore trends calculated from your locally stored report records.',`<button class="btn secondary" data-action="csv-export">Export CSV</button> ${btn('print-summary','Print summary','primary')}`)}<section class="panel"><div class="filters">${selectFilter('Category','analytics-category',cats,analyticsFilters.category||'')}${selectFilter('Status','analytics-status',statuses,analyticsFilters.status||'')}<label class="filter-field"><span>From</span><input type="date" data-filter="analytics-from" value="${analyticsFilters.from||''}"></label><label class="filter-field"><span>To</span><input type="date" data-filter="analytics-to" value="${analyticsFilters.to||''}"></label><button class="btn subtle" data-action="clear-analytics">Clear filters</button></div></section><section class="analytics-grid analytics-full"><article class="panel reports-panel"><div class="panel-heading"><div><h2>Monthly report trends</h2><p>Based on filtered report data</p></div></div><div class="dashboard-bars">${monthly.map(x=>`<div class="bar-column"><span>${x.n}</span><div style="height:${Math.max(5,x.n/Math.max(1,...monthly.map(y=>y.n))*100)}%"></div><small>${x.label}</small></div>`).join('')}</div></article><article class="panel category-panel"><div class="panel-heading"><div><h2>Resolved vs unresolved</h2><p>${rows.filter(r=>['Resolved','Closed'].includes(r.status)).length} resolved · ${rows.filter(r=>!['Resolved','Closed','Rejected'].includes(r.status)).length} unresolved</p></div></div><div class="resolution-meter"><span style="width:${rows.length?rows.filter(r=>['Resolved','Closed'].includes(r.status)).length/rows.length*100:0}%"></span></div><p class="sample-note">Rejected reports excluded from unresolved totals.</p></article></section><section class="analytics-grid"><article class="panel analytics-list"><h2>Reports by category</h2>${metricList(groups('category',cats),rows.length)}</article><article class="panel analytics-list"><h2>Reports by status</h2>${metricList(groups('status',statuses),rows.length)}</article><article class="panel analytics-list"><h2>Reports by severity</h2>${metricList(groups('severity',SEVERITIES),rows.length)}</article><article class="panel analytics-list"><h2>Resident reporting statistics</h2>${d.residents.map(r=>`<div class="metric-row"><span>${esc(r.name)}</span><b>${d.reports.filter(x=>x.residentId===r.id).length} reports</b></div>`).join('')||'No residents yet'}</article></section><p class="sample-note">Year-to-date records: ${rows.filter(r=>new Date(r.createdAt).getFullYear()===new Date().getFullYear()).length} · All records: ${rows.length}. Sample records are marked in the initial dataset and are only for demonstration.</p>`}
function metricList(items,total){return items.map(([name,n])=>`<div class="metric-row"><span>${esc(name)}</span><b>${n} <small>${total?Math.round(n/total*100):0}%</small></b></div>`).join('')||'<p class="sample-note">No data for selected filters.</p>'}
function alertsPage(){const d=store.get(),categories=['Flood','Fire','Earthquake','Severe Weather','Medical Emergency','Road Accident','Crime or Security','General Advisory','Other'],rows=d.alerts.filter(a=>!alertQuery||`${a.title} ${a.category} ${a.location}`.toLowerCase().includes(alertQuery.toLowerCase())).filter(a=>!alertFilters.status||a.status===alertFilters.status).filter(a=>!alertFilters.category||a.category===alertFilters.category).filter(a=>!alertFilters.severity||a.severity===alertFilters.severity);return `${header('Emergency Alerts','Create local alert records and manage their publication status.',btn('new-alert','＋ Create alert'))}<div class="integration-note"><strong>Standalone demo:</strong> Publishing updates this admin dashboard only. Residents have not received these alerts because the Resident App is not connected.</div><section class="panel"><div class="filters"><label class="filter-field"><span>Search alerts</span><input id="alertSearch" value="${esc(alertQuery)}" placeholder="Title, category, location"></label>${selectFilter('Status','alert-status',['Draft','Published','Archived'],alertFilters.status||'')}${selectFilter('Category','alert-category',categories,alertFilters.category||'')}${selectFilter('Severity','alert-severity',SEVERITIES,alertFilters.severity||'')}</div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>ALERT</th><th>CATEGORY</th><th>SEVERITY</th><th>TARGET LOCATION</th><th>STATUS</th><th>CREATED</th><th>ACTIONS</th></tr></thead><tbody>${rows.map(a=>`<tr><td><button class="table-link" data-action="view-alert" data-id="${a.id}"><strong>${esc(a.title)}</strong><small>${esc(a.id)}${a.sample?' · SAMPLE':''}</small></button></td><td>${esc(a.category)}</td><td>${badge(a.severity)}</td><td>${esc(a.location)}</td><td>${badge(a.status)}</td><td>${date(a.createdAt)}</td><td class="actions-cell"><button class="tiny-btn" data-action="view-alert" data-id="${a.id}">View</button><button class="tiny-btn" data-action="edit-alert" data-id="${a.id}">Edit</button>${a.status==='Draft'?`<button class="tiny-btn" data-action="publish-alert" data-id="${a.id}">Publish</button><button class="tiny-btn danger-text" data-action="delete-draft" data-id="${a.id}">Delete</button>`:a.status==='Published'?`<button class="tiny-btn" data-action="archive-alert" data-id="${a.id}">Archive</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('No alerts found','Create an alert draft to get started.')}</section>`}
function activityPage(){const d=store.get(),q=(document.getElementById('activitySearch')?.value||'').toLowerCase(),actions=[...new Set(d.activity.map(a=>a.action))],rows=d.activity.filter(a=>!q||`${a.id} ${a.admin} ${a.action} ${a.affected}`.toLowerCase().includes(q)).filter(a=>!activityFilters.action||a.action===activityFilters.action).filter(a=>!activityFilters.from||a.date.slice(0,10)>=activityFilters.from).filter(a=>!activityFilters.to||a.date.slice(0,10)<=activityFilters.to);const pages=Math.max(1,Math.ceil(rows.length/12));activityPageNumber=Math.min(activityPageNumber,pages);const shown=rows.slice((activityPageNumber-1)*12,activityPageNumber*12);return `${header('Activity Logs','A locally stored audit trail of administrative actions.') }<section class="panel"><div class="filters"><label class="filter-field"><span>Search activity</span><input id="activitySearch" value="${esc(q)}" placeholder="Action, admin, record ID"></label>${selectFilter('Action type','activity-action',actions,activityFilters.action||'')}<label class="filter-field"><span>From</span><input type="date" data-filter="activity-from" value="${activityFilters.from||''}"></label><label class="filter-field"><span>To</span><input type="date" data-filter="activity-to" value="${activityFilters.to||''}"></label><span class="sample-note">Logs are read-only in this interface</span></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>ACTIVITY ID</th><th>ADMINISTRATOR</th><th>ACTION</th><th>AFFECTED RECORD</th><th>DATE &amp; TIME</th></tr></thead><tbody>${shown.map(a=>`<tr><td>${esc(a.id)}</td><td>${esc(a.admin)}</td><td>${esc(a.action)}</td><td>${esc(a.affected)}</td><td>${dateTime(a.date)}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${rows.length} recorded actions</span><div><button data-action="activity-page" data-value="${Math.max(1,activityPageNumber-1)}">‹</button><span>Page ${activityPageNumber} of ${pages}</span><button data-action="activity-page" data-value="${Math.min(pages,activityPageNumber+1)}">›</button></div></div>`:empty('No activity recorded','Login, reports, alerts, and settings changes are logged here.')}</section>`}
function archivesPage(){const d=store.get(),rows=d.archives.filter(r=>!searchText||`${r.id} ${r.title} ${r.category} ${r.location}`.toLowerCase().includes(searchText.toLowerCase())).filter(r=>!reportFilters.category||r.category===reportFilters.category).filter(r=>!reportFilters.archiveFrom||r.archivedAt?.slice(0,10)>=reportFilters.archiveFrom).filter(r=>!reportFilters.archiveTo||r.archivedAt?.slice(0,10)<=reportFilters.archiveTo);return `${header('Report Archives','Review, restore, or permanently remove archived reports.') }<section class="panel"><div class="filters"><label class="filter-field"><span>Search archive</span><input id="globalSearchMirror" value="${esc(searchText)}" placeholder="Search archived reports"></label>${selectFilter('Category','archive-category',[...new Set(d.archives.map(r=>r.category))],reportFilters.category||'')}<label class="filter-field"><span>Archived from</span><input type="date" data-filter="archive-archiveFrom" value="${reportFilters.archiveFrom||''}"></label><label class="filter-field"><span>Archived to</span><input type="date" data-filter="archive-archiveTo" value="${reportFilters.archiveTo||''}"></label></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>REPORT</th><th>CATEGORY</th><th>LOCATION</th><th>ORIGINAL STATUS</th><th>ARCHIVED</th><th>ACTIONS</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="table-link" data-action="view-report" data-id="${r.id}" data-archive="1"><strong>${esc(r.title)}</strong><small>#${esc(r.id)}</small></button></td><td>${esc(r.category)}</td><td>${esc(r.location)}</td><td>${badge(r.status)}</td><td>${date(r.archivedAt)}</td><td class="actions-cell"><button class="tiny-btn" data-action="restore-report" data-id="${r.id}">Restore</button><button class="tiny-btn danger-text" data-action="delete-archive" data-id="${r.id}">Delete forever</button></td></tr>`).join('')}</tbody></table></div>`:empty('Archive is empty','Archived reports will appear here.')}</section>`}
function maintenanceCard(name,cfg){const label=name==='Resident/User Page'?'Resident Page / Resident Application':name==='Official Page'?'Official Page / Official Dashboard':name;return `<form class="maintenance-card" data-form="maintenance" data-name="${esc(name)}"><div class="maintenance-card-heading"><h3>${esc(label)}</h3><span class="status ${cfg.enabled?'status-active':'status-draft'}">${cfg.enabled?'Active':'Inactive'}</span></div><label class="checkline"><input type="checkbox" name="enabled" ${cfg.enabled?'checked':''}> Enable maintenance mode</label><label>Announcement title<input name="title" value="${esc(cfg.title)}" placeholder="Scheduled maintenance"></label><label>Announcement<textarea name="message" rows="2" placeholder="Message shown to users">${esc(cfg.message)}</textarea></label><label>Reason or description<textarea name="reason" rows="2" placeholder="Describe the planned work">${esc(cfg.reason||'')}</textarea></label><label>Scheduled start<input name="start" type="datetime-local" value="${esc(cfg.start)}"></label><label>Expected completion<input name="end" type="datetime-local" value="${esc(cfg.end)}"></label><button class="btn secondary">Save maintenance settings</button></form>`}
function settingsPage(){const d=store.get(),m=d.settings.maintenance;return `${header('Settings','Manage your local administrator profile and demo preferences.') }<div class="settings-grid"><section class="panel settings-panel"><h2>Administrator profile</h2><p>Profile details used in this local demo.</p><form data-form="profile"><label>Full name<input name="name" required minlength="2" value="${esc(d.admin.name)}"></label><label>Email<input name="email" type="email" required value="${esc(d.admin.email)}"></label><label>Contact number<input name="contact" required value="${esc(d.admin.contact)}"></label><label>Profile picture URL <small>(optional)</small><input name="picture" type="url" value="${esc(d.admin.picture)}" placeholder="https://..."></label><button class="btn primary">Save profile</button></form></section><section class="panel settings-panel"><h2>Change demo password</h2><p>This updates the local demo credentials only.</p><form data-form="password"><label>Current password<input name="oldPassword" type="password" required></label><label>New password<input name="newPassword" type="password" minlength="8" required></label><label>Confirm new password<input name="confirmPassword" type="password" minlength="8" required></label><button class="btn primary">Update password</button></form><hr><h2>Notification preferences</h2><form data-form="notifications">${Object.entries(d.settings.notifications).map(([key,val])=>`<label class="checkline"><input type="checkbox" name="${key}" ${val?'checked':''}> Notify me about ${key}</label>`).join('')}<button class="btn secondary">Save preferences</button></form></section></div><section class="panel maintenance-panel"><div class="panel-heading"><div><h2>Maintenance Management</h2><p>Enable or schedule maintenance for the Resident and Official interfaces.</p></div></div><div class="integration-note"><strong>Local demo storage:</strong> Settings are saved in this browser. Resident and Official interfaces must use this shared maintenance setting to show the maintenance page; those separate interfaces are not included in this checkout.</div><div class="maintenance-grid">${Object.entries(m).map(([name,cfg])=>maintenanceCard(name,cfg)).join('')}</div><h3>Maintenance history</h3>${d.settings.maintenanceHistory.length?`<div class="table-scroll"><table><thead><tr><th>INTERFACE</th><th>STATUS / ACTION</th><th>ADMINISTRATOR</th><th>CHANGED</th></tr></thead><tbody>${d.settings.maintenanceHistory.map(h=>`<tr><td>${esc(h.name)}</td><td>${h.enabled?'Active':'Inactive'} · ${esc(h.action||'Maintenance settings updated')}</td><td>${esc(h.admin||'Administrator')}</td><td>${dateTime(h.changedAt)}</td></tr>`).join('')}</tbody></table></div>`:empty('No maintenance changes','Saved maintenance updates will be listed here.')}</section>`}
function maintenanceView(platform,cfg){const label=platform==='Resident/User Page'?'Resident Page / Resident Application':'Official Page / Official Dashboard';return `<main class="maintenance-screen"><section class="maintenance-screen-card"><span class="maintenance-screen-mark">${icon('alerts')}</span><span class="maintenance-kicker">${esc(label)}</span><h1>${esc(cfg.title||'Scheduled maintenance')}</h1><p>${esc(cfg.message||'This interface is temporarily unavailable while scheduled maintenance is in progress.')}</p>${cfg.reason?`<div class="maintenance-reason"><strong>Reason</strong><p>${esc(cfg.reason)}</p></div>`:''}${cfg.start||cfg.end?`<div class="maintenance-schedule"><strong>Expected schedule</strong>${cfg.start?`<span>Starts: ${dateTime(cfg.start)}</span>`:''}${cfg.end?`<span>Expected completion: ${dateTime(cfg.end)}</span>`:''}</div>`:''}<span class="maintenance-active-label">Maintenance is active</span></section></main>`}function render(){const session=store.session();if(!session){app.innerHTML=loginView();return}const adminEmail=store.loginInfo().email;if(session.role==='Resident'||session.role==='Official'){const platform=session.role==='Resident'?'Resident/User Page':'Official Page';const maintenance=store.getMaintenance(platform);if(maintenance.enabled){app.innerHTML=maintenanceView(platform,maintenance);return}}if(session.role!=='Administrator'||session.email?.toLowerCase()!==adminEmail.toLowerCase()){app.innerHTML=`<main class="login-screen"><section class="login-card"><span class="login-kicker">ROLE ACCESS</span><h1>Admin access required</h1><p>This standalone build provides an Administrator interface only. Resident account management is restricted to authenticated Administrators.</p><button class="btn primary" data-action="logout">Sign out</button></section></main>`;return}const views={dashboard,reports:reportsPage,map:mapPage,residents:residentsPage,analytics:analyticsPage,alerts:alertsPage,activity:activityPage,archives:archivesPage,settings:settingsPage};app.innerHTML=shell((views[page]||dashboard)());}
function loginView(){const d=store.loginInfo();return `<main class="login-screen"><section class="login-card"><div class="login-brand"><span class="brand-mark">${icon('alerts')}</span><div><strong>Alert Barangay</strong><small>ADMIN PORTAL</small></div></div><span class="login-kicker">BARANGAY SAN ISIDRO</span><h1>Welcome back</h1><p>Sign in to manage community reports and alerts.</p><form data-form="login"><label>Email address<input type="email" name="email" autocomplete="username" required value="${esc(d.email)}"></label><label>Password<div class="password-wrap"><input id="loginPassword" type="password" name="password" autocomplete="current-password" required><button type="button" data-action="toggle-password">Show</button></div></label><label class="checkline"><input type="checkbox" name="remember" checked> Remember this device</label><div id="loginError" class="form-error" role="alert"></div><button class="btn primary login-submit">Sign in</button></form><div class="demo-credentials"><strong>Demo credentials</strong><span>Email: ${esc(d.email)}</span><span>Password: ${esc(d.password)}</span><small>Local demo authentication is not production-secure.</small></div></section><p class="login-foot">Alert Barangay · Standalone local demonstration</p></main>`}
document.addEventListener('click',event=>{const link=event.target.closest('[data-page]');if(link){event.preventDefault();setPage(link.dataset.page);document.getElementById('sidebar')?.classList.remove('open');return}const b=event.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,getData=()=>store.get();switch(b.dataset.action){case'menu':document.getElementById('sidebar')?.classList.toggle('open');break;case'mobile-search':if(innerWidth<=760){mobileSearchOpen=true;document.getElementById('globalSearch').focus()}break;case'stat-nav':reportFilters.status=b.dataset.label==='Pending Reports'?'Pending':'';setPage(b.dataset.target);break;case'go-analytics':setPage('analytics');break;case'new-report':openReportForm();break;case'view-report':viewReport(id,b.dataset.archive==='1');break;case'edit-report':openReportForm(getData().reports.find(r=>r.id===id));break;case'archive-report':if(confirm(`Archive report ${id}? It can be restored later.`)){store.archiveReport(id);closeModal();render();notify('Report archived.')}break;case'report-page':reportPage=Number(b.dataset.value);render();break;case'clear-report-filters':reportFilters={};searchText='';render();break;case'new-resident':if(store.session()?.role==='Administrator')openResidentForm();else notify('Administrator access required.',true);break;case'edit-resident':if(store.session()?.role==='Administrator')openResidentForm(getData().residents.find(r=>r.id===id));else notify('Administrator access required.',true);break;case'view-resident':if(store.session()?.role==='Administrator')viewResident(id);else notify('Administrator access required.',true);break;case'resident-status':{if(store.session()?.role!=='Administrator'){notify('Administrator access required.',true);break}const target=b.dataset.status;const resident=getData().residents.find(r=>r.id===id);if(!resident)break;let reason=target==='Active'?'Account reactivated by administrator.':prompt(`Enter the reason for setting this account to ${target}:`);if(target!=='Active'&&!reason?.trim()){notify('A reason is required to restrict or block an account.',true);break}if(!confirm(`${target==='Active'?'Reactivate':target==='Blocked'?'Block':'Restrict'} ${resident.name}'s account?`))break;try{store.setResidentStatus(id,target,reason);render();notify(`Resident account ${target.toLowerCase()}.`)}catch(error){notify(error.message,true)}break}case'new-alert':openAlertForm();break;case'edit-alert':openAlertForm(getData().alerts.find(a=>a.id===id));break;case'view-alert':viewAlert(id);break;case'publish-alert':if(confirm('Publish this alert in the local admin demo? It will not be sent to residents.')){store.updateAlert(id,{status:'Published',publishedAt:new Date().toISOString()},'Published emergency alert');render();notify('Alert published locally. Residents have not been notified.')}break;case'archive-alert':if(confirm('Archive this published alert?')){store.updateAlert(id,{status:'Archived',archivedAt:new Date().toISOString()},'Archived emergency alert');render();notify('Alert archived.')}break;case'delete-draft':store.deleteDraft(id);render();break;case'restore-report':if(confirm('Restore this report to Report Management?')){store.restoreReport(id);render();notify('Report restored.')}break;case'delete-archive':store.deleteArchive(id);render();break;case'activity-page':activityPageNumber=Number(b.dataset.value);render();break;case'csv-export':exportCsv();break;case'print-summary':window.print();break;case'profile-menu':togglePopover('profile');break;case'notifications':togglePopover('notifications');break;case'mark-read':store.markNotificationsRead();togglePopover('notifications');break;case'mark-notification-read':store.markNotificationRead(id);togglePopover('notifications');break;case'logout':store.logout();page='dashboard';render();notify('You have been signed out.');break;case'profile-settings':setPage('settings');break;case'my-profile':setPage('settings');break;case'close-modal':closeModal();break;case'toggle-password':{const p=document.getElementById('loginPassword');p.type=p.type==='password'?'text':'password';b.textContent=p.type==='password'?'Show':'Hide';break}case'close-popover':document.getElementById('popover').innerHTML='';break;case'clear-analytics':analyticsFilters={};render();break;case'clear-search':searchText='';render();break;case'close-map':break;}}
);
document.addEventListener('input',event=>{if(event.target.id==='globalSearch'||event.target.id==='globalSearchMirror'){searchText=event.target.value;if(event.target.id==='globalSearch'&&searchText&& !['reports','archives','map'].includes(page)){page='reports';location.hash='reports'}renderPreserveFocus(event.target.id,event.target.selectionStart)}if(event.target.id==='reportSearch'){searchText=event.target.value;reportPage=1;renderPreserveFocus('reportSearch',event.target.selectionStart)}if(event.target.id==='residentSearch'){residentQuery=event.target.value;renderPreserveFocus('residentSearch',event.target.selectionStart)}if(event.target.id==='alertSearch'){alertQuery=event.target.value;renderPreserveFocus('alertSearch',event.target.selectionStart)}if(event.target.id==='activitySearch'){activityPageNumber=1;renderPreserveFocus('activitySearch',event.target.selectionStart)}});
function renderPreserveFocus(id,pos){render();const el=document.getElementById(id);if(el){el.focus();el.setSelectionRange?.(pos,pos)}}
document.addEventListener('change',event=>{const key=event.target.dataset.filter;if(!key)return;const v=event.target.value;if(key.startsWith('analytics-'))analyticsFilters[key.replace('analytics-','')]=v;else if(key.startsWith('archive-'))reportFilters[key.replace('archive-','')]=v;else if(key.startsWith('activity-'))activityFilters[key.replace('activity-','')]=v;else if(key.startsWith('resident-'))reportFilters[key.replace('resident-','')]=v;else if(key.startsWith('alert-'))alertFilters[key.replace('alert-','')]=v;else reportFilters[key]=v;reportPage=1;render()});
document.addEventListener('change',event=>{const file=event.target.closest('[data-image-file]')?.files?.[0];if(!file)return;if(file.size>400*1024){event.target.value='';notify('Image must be 400 KB or smaller to protect browser storage.',true);return}if(!file.type.startsWith('image/')){event.target.value='';notify('Choose an image file.',true);return}const reader=new FileReader();reader.onload=()=>{let preview=event.target.closest('label').querySelector('.upload-preview');if(!preview){preview=document.createElement('img');preview.className='upload-preview';event.target.closest('label').append(preview)}preview.src=reader.result};reader.onerror=()=>notify('Could not preview this image.',true);reader.readAsDataURL(file)});
function readSmallImage(file){return new Promise((resolve,reject)=>{if(!file?.size){resolve('');return}if(file.size>400*1024){reject(new Error('Image must be 400 KB or smaller to protect browser storage.'));return}if(!file.type.startsWith('image/')){reject(new Error('Choose a valid image file.'));return}const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read image file.'));reader.readAsDataURL(file)})}
document.addEventListener('submit',async event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const type=form.dataset.form,fd=new FormData(form),data=Object.fromEntries(fd.entries());try{if(type==='login'){const ok=store.login(data.email,data.password,fd.has('remember'));if(!ok){document.getElementById('loginError').textContent='Email or password is incorrect.';return}render();notify('Welcome to the admin portal.');return}if(type==='report'){const attachmentFile=fd.get('attachmentFile');const attachment=attachmentFile?.size?await readSmallImage(attachmentFile):data.attachment||'';const values={title:data.title.trim(),category:data.category,description:data.description.trim(),location:data.location.trim(),lat:Number(data.lat),lng:Number(data.lng),severity:data.severity,status:data.status,residentId:data.residentId||'',assignedTo:data.assignedTo.trim(),remarks:data.remarks.trim(),attachment};if(values.status==='Rejected'&&!confirm('Reject this report? This decision will be recorded in report history.'))return;if(form.dataset.id)store.updateReport(form.dataset.id,values,values.status==='Rejected'?'Rejected report':'Edited report details');else store.saveReport(values);closeModal();render();notify('Report saved.');return}if(type==='resident'){const values={name:data.name.trim(),email:data.email.trim(),phone:data.phone.trim(),address:data.address.trim(),status:data.status};store.saveResident(values,form.dataset.id||null);closeModal();render();notify('Resident account saved.');return}if(type==='alert'){const current=form.dataset.id?store.get().alerts.find(a=>a.id===form.dataset.id):null;if(data.location!=='Entire Barangay'&&!data.areaDetail.trim())throw new Error('Add the specific purok, street, or area for this alert.');const uploaded=fd.get('imageFile');const image=uploaded?.size?await readSmallImage(uploaded):data.image||current?.image||'';const location=data.areaDetail.trim()?`${data.location} — ${data.areaDetail.trim()}`:data.location;const values={title:data.title.trim(),category:data.category,severity:data.severity,location,details:data.details.trim(),instructions:data.instructions.trim(),image,status:data.status||'Draft'};if(values.status==='Published'&&current?.status!=='Published'&&!confirm('Publish this alert locally? Residents will not receive it because the Resident App is not connected.'))return;if(current&&current.status==='Published'&&data.status==='Published')store.updateAlert(form.dataset.id,values,'Edited published alert');else store.saveAlert(values,form.dataset.id||null);closeModal();render();notify('Alert saved as '+(values.status||'Draft').toLowerCase()+'.');return}if(type==='profile'){store.updateProfile({name:data.name.trim(),email:data.email.trim(),contact:data.contact.trim(),picture:data.picture.trim()});render();notify('Profile saved.');return}if(type==='password'){if(data.newPassword!==data.confirmPassword)throw new Error('New passwords do not match.');store.changePassword(data.oldPassword,data.newPassword);render();notify('Demo password updated.');return}if(type==='notifications'){const notifications={reports:fd.has('reports'),alerts:fd.has('alerts'),residents:fd.has('residents')};store.saveSettings({notifications});render();notify('Notification preferences saved.');return}if(type==='maintenance'){const name=form.dataset.name;store.saveMaintenance(name,{enabled:fd.has('enabled'),title:data.title.trim(),message:data.message.trim(),reason:data.reason.trim(),start:data.start,end:data.end});render();notify(`${name} maintenance settings saved locally.`);return}}catch(error){notify(error.message||'Could not save changes.',true)}});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();mobileSearchOpen=true;document.getElementById('globalSearch')?.focus()}if(event.key==='Escape'){mobileSearchOpen=false;closeModal();document.getElementById('popover').innerHTML='';document.getElementById('sidebar')?.classList.remove('open')}});

function modal(title,body,wide=false){document.getElementById('modal').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal-card ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}" onclick="event.stopPropagation()"><div class="modal-head"><div><h2>${esc(title)}</h2></div><button class="icon-button" data-action="close-modal" aria-label="Close">${icon('close')}</button></div>${body}</section></div>`}
function closeModal(){document.getElementById('modal').innerHTML=''}
function field(label,name,value='',type='text',required=true,extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`}
function optionList(options,value){return options.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}
function openReportForm(r=null){const d=store.get();modal(r?'Edit report':'Create report',`<form class="form-grid" data-form="report" ${r?`data-id="${r.id}"`:''}>${field('Incident title','title',r?.title||'') }<label>Category<select name="category">${optionList(CATEGORIES,r?.category||'Public Safety')}</select></label><label>Severity<select name="severity">${optionList(SEVERITIES,r?.severity||'Medium')}</select></label><label>Status<select name="status">${optionList(STATUS,r?.status||'Submitted')}</select></label>${field('Location','location',r?.location||'')}${field('Latitude','lat',r?.lat??14.6,'number',true,'step="any"')}${field('Longitude','lng',r?.lng??120.98,'number',true,'step="any"')}<label>Resident reporter<select name="residentId"><option value="">Unassigned</option>${d.residents.map(x=>`<option value="${x.id}" ${x.id===r?.residentId?'selected':''}>${esc(x.name)} — ${x.id}</option>`).join('')}</select></label>${field('Assigned personnel/team','assignedTo',r?.assignedTo||'', 'text',false)}<label class="span-two">Description<textarea name="description" rows="3" required>${esc(r?.description||'')}</textarea></label><label class="span-two">Administrative remarks<textarea name="remarks" rows="2">${esc(r?.remarks||'')}</textarea></label>${field('Attachment URL (optional)','attachment',r?.attachment||'','url',false)}<label class="span-two">Or attach a small image (max 400 KB)<input type="file" name="attachmentFile" accept="image/*" data-image-file></label>${r?.attachment?`<div class="span-two image-preview"><img src="${esc(r.attachment)}" alt="Attachment preview"></div>`:''}<div class="form-actions span-two"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary">Save report</button></div></form>`,true)}
function viewReport(id,archived=false){const r=(archived?store.get().archives:store.get().reports).find(x=>x.id===id)||store.get().reports.find(x=>x.id===id)||store.get().archives.find(x=>x.id===id);if(!r)return;const resident=store.get().residents.find(x=>x.id===r.residentId);modal(`Report ${r.id}`,`<div class="detail-grid"><div><small>INCIDENT</small><strong>${esc(r.title)}</strong></div><div><small>CATEGORY / SEVERITY</small><strong>${esc(r.category)} · ${esc(r.severity)}</strong></div><div><small>STATUS</small>${badge(r.status)}</div><div><small>LOCATION</small><strong>${esc(r.location)}</strong></div><div><small>COORDINATES</small><strong>${Number(r.lat).toFixed(5)}, ${Number(r.lng).toFixed(5)} <span class="sample-note">(sample location)</span></strong></div><div><small>REPORTED BY</small><strong>${resident?esc(resident.name):'Not linked to a resident'}</strong></div><div><small>ASSIGNED TO</small><strong>${esc(r.assignedTo||'Unassigned')}</strong></div><div><small>SUBMITTED</small><strong>${dateTime(r.createdAt)}</strong></div><div class="span-two"><small>DESCRIPTION</small><p>${esc(r.description)}</p></div><div class="span-two"><small>ADMINISTRATIVE REMARKS</small><p>${esc(r.remarks||'No remarks added.')}</p></div>${r.attachment?`<div class="span-two"><small>ATTACHMENT</small><a href="${esc(r.attachment)}" target="_blank" rel="noopener">Open attachment</a></div>`:''}<div class="span-two"><small>REPORT HISTORY</small>${r.history?.length?r.history.map(h=>`<p>${dateTime(h.date)} — ${esc(h.admin)}: ${esc(h.changes)}</p>`).join(''):'<p>No changes recorded yet.</p>'}</div></div><div class="form-actions"><button class="btn secondary" data-action="close-modal">Close</button>${!archived?`<button class="btn secondary" data-action="edit-report" data-id="${r.id}">Edit details</button><button class="btn secondary" data-action="archive-report" data-id="${r.id}">Archive</button>`:''}</div>` ,true)}
function openResidentForm(r=null){modal(r?'Edit resident':'Add resident',`<form class="form-grid" data-form="resident" ${r?`data-id="${r.id}"`:''}>${field('Full name','name',r?.name||'')}${field('Email address','email',r?.email||'','email')}${field('Contact number','phone',r?.phone||'')}${field('Address','address',r?.address||'')}<p class="sample-note span-two">Account access status can only be changed using the Restrict, Block, or Reactivate controls in Resident Accounts.</p><div class="form-actions span-two"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary">Save resident</button></div></form>`)}
function viewResident(id){const r=store.get().residents.find(x=>x.id===id);if(!r)return;const reports=store.get().reports.filter(x=>x.residentId===id);const actions=store.get().activity.filter(x=>x.affected===id||x.affected.startsWith(`${id} —`)).slice(0,8);const history=r.restrictionHistory||[];modal(`Resident profile · ${r.id}`,`<div class="detail-grid"><div><small>NAME</small><strong>${esc(r.name)}</strong></div><div><small>ACCOUNT STATUS</small>${badge(residentStatus(r))}</div><div><small>EMAIL</small><strong>${esc(r.email)}</strong></div><div><small>CONTACT</small><strong>${esc(r.phone)}</strong></div><div><small>ADDRESS</small><strong>${esc(r.address)}</strong></div><div><small>ACCOUNT CREATED</small><strong>${date(r.createdAt)}</strong></div><div class="span-two"><small>RESTRICTION HISTORY (${history.length})</small>${history.length?`<div class="restriction-history">${history.map(h=>`<article><div>${badge(h.status)} <strong>${esc(h.admin)}</strong><time>${dateTime(h.date)}</time></div><p><b>Reason:</b> ${esc(h.reason)}</p></article>`).join('')}</div>`:'<p>No restriction actions recorded.</p>'}</div><div class="span-two"><small>SUBMITTED REPORTS (${reports.length})</small>${reports.length?reports.map(x=>`<p><button class="table-link" data-action="view-report" data-id="${x.id}"><strong>${esc(x.title)}</strong> · ${esc(x.status)}</button></p>`).join(''):'<p>No reports linked to this resident.</p>'}</div><div class="span-two"><small>RECENT ACCOUNT ACTIVITY</small>${actions.length?actions.map(x=>`<p>${dateTime(x.date)} · ${esc(x.action)} · ${esc(x.affected)}</p>`).join(''):'<p>No account changes recorded.</p>'}</div></div><div class="form-actions"><button class="btn secondary" data-action="close-modal">Close</button><button class="btn primary" data-action="edit-resident" data-id="${id}">Edit resident</button></div>`,true)}
function openAlertForm(a=null){const categories=['Flood','Fire','Earthquake','Severe Weather','Medical Emergency','Road Accident','Crime or Security','General Advisory','Other'];const targets=['Entire Barangay','Specific Purok','Specific Street','Specific Area'];modal(a?'Edit emergency alert':'Create emergency alert',`<form class="form-grid" data-form="alert" ${a?`data-id="${a.id}"`:''}>${field('Alert title','title',a?.title||'')}<label>Category<select name="category">${optionList(categories,a?.category||'General Advisory')}</select></label><label>Severity<select name="severity">${optionList(SEVERITIES,a?.severity||'Medium')}</select></label><label>Target location<select name="location">${optionList(targets,a?.location?.split(' — ')[0]||'Entire Barangay')}</select></label>${field('Specific location detail (optional)','areaDetail',a?.areaDetail||a?.location?.split(' — ')[1]||'', 'text',false)}<label>Status<select name="status">${optionList(['Draft','Published','Archived'],a?.status||'Draft')}</select></label><label class="span-two">Announcement details<textarea name="details" rows="3" required>${esc(a?.details||'')}</textarea></label><label class="span-two">Instructions for residents<textarea name="instructions" rows="3">${esc(a?.instructions||'')}</textarea></label><label class="span-two">Image URL (optional)<input type="url" name="image" value="${esc(a?.image||'')}" placeholder="https://..."></label><label class="span-two">Or upload an image (max 400 KB)<input type="file" name="imageFile" accept="image/*" data-image-file></label>${a?.image?`<div class="span-two image-preview"><img src="${esc(a.image)}" alt="Alert image preview"></div>`:''}<p class="sample-note span-two">Publishing changes only the local admin record. No residents will receive this alert.</p><div class="form-actions span-two"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary">Save alert</button></div></form>` ,true)}
function viewAlert(id){const a=store.get().alerts.find(x=>x.id===id);if(!a)return;modal(`Emergency alert · ${a.id}`,`<div class="detail-grid"><div><small>TITLE</small><strong>${esc(a.title)}</strong></div><div><small>STATUS / SEVERITY</small>${badge(a.status)} ${badge(a.severity)}</div><div><small>CATEGORY</small><strong>${esc(a.category)}</strong></div><div><small>TARGET</small><strong>${esc(a.location)}</strong></div><div class="span-two"><small>ANNOUNCEMENT</small><p>${esc(a.details)}</p></div><div class="span-two"><small>INSTRUCTIONS</small><p>${esc(a.instructions||'No instructions.')}</p></div>${a.image?`<div class="span-two"><img class="alert-preview" src="${esc(a.image)}" alt="Alert attachment preview"></div>`:''}<div><small>CREATED</small><strong>${dateTime(a.createdAt)}</strong></div></div><div class="form-actions"><button class="btn secondary" data-action="close-modal">Close</button><button class="btn primary" data-action="edit-alert" data-id="${id}">Edit alert</button></div>` ,true)}
function togglePopover(which){const p=document.getElementById('popover');if(!p)return;if(p.dataset.which===which){p.innerHTML='';p.dataset.which='';return}p.dataset.which=which;if(which==='profile'){const a=store.get().admin;p.innerHTML=`<div class="popover profile-popover"><strong>${esc(a.name)}</strong><small>${esc(a.email)}</small><button data-action="my-profile">My Profile</button><button data-action="profile-settings">Settings</button><button class="danger-text" data-action="logout">Sign out</button></div>`}else{const ns=store.get().notifications;p.innerHTML=`<div class="popover notification-popover"><div class="popover-head"><strong>Notifications</strong><button data-action="mark-read">Mark All as Read</button></div>${ns.length?ns.map(n=>`<button class="notification-row ${n.read?'':'unread'}" data-action="mark-notification-read" data-id="${esc(n.id)}" ${n.read?'disabled':''}><span aria-hidden="true">${n.read?'○':'●'}</span><span class="notification-message"><strong>${esc(n.title||'Notification')}</strong><span>${esc(n.message)}</span><small>${esc(n.recipient||'Administrator')} · ${timeAgo(n.date)}</small></span></button>`).join(''):'<div class="notification-empty">No notifications yet.</div>'}</div>`}}
function exportCsv(){const rows=store.get().reports.filter(r=>!analyticsFilters.category||r.category===analyticsFilters.category).filter(r=>!analyticsFilters.status||r.status===analyticsFilters.status).filter(r=>!analyticsFilters.from||r.createdAt.slice(0,10)>=analyticsFilters.from).filter(r=>!analyticsFilters.to||r.createdAt.slice(0,10)<=analyticsFilters.to);const cols=['id','title','category','location','severity','status','createdAt','assignedTo','residentId','description','remarks'];const csv=[cols.join(','),...rows.map(r=>cols.map(k=>`"${String(r[k]??'').replaceAll('"','""')}"`).join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`barangay-reports-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify(`CSV export downloaded (${rows.length} filtered reports).`)}
window.addEventListener('hashchange',()=>{const requested=location.hash.slice(1)||'dashboard';if(nav.some(n=>n[0]===requested)){page=requested;render()}});
store.subscribe(()=>{if(store.session())render()});
render();
})();
